import json,hashlib
from pathlib import Path
root=Path("/srv/projects/telegram-robot-leads")
files=("optin/scripts/telegram-robot-leads-status.sh","scripts/telegram-robot-leads-status.sh","optin/scripts/lead_health.py","scripts/lead_health.py")
