  data=p.read_bytes()
  v.update(sha256=hashlib.sha256(data).hexdigest(),size=len(data),lines=len(data.splitlines()))
  if p.suffix==".sh":
   lines=[]
   for n,line in enumerate(data.decode("utf-8","replace").splitlines(),1):
