     lines.append(f"{n}:{line[:160]}")
   v["status_relevant_lines"]=lines[:40]
 out["files"][rel]=v
scripts=root/"optin/scripts"
if scripts.is_dir():
 for p in sorted(scripts.iterdir()):
  if p.is_file():
   out["optin_scripts"].append({"name":p.name,"size":p.stat().st_size,"symlink":p.is_symlink()})
print(json.dumps(out,sort_keys=True))
